-- Generated by `make contracts` from contracts/census_county_pop.odcs.yaml. Do not edit: change the contract and regenerate.
-- Business rules from the contract only: total rows, renamed labels, partial places, flag meanings,
-- then the conformed condition, place and time keys (conformedDimensions). Nothing is removed or
-- changed: each rule adds a column beside the published values.
with stg as (
    select * from {{ ref('stg_census_county_pop') }}
),

ruled as (
    select
      stg.*,
      coalesce((sumlev = '040'), false) AS "is_total_row"
    from stg
),

keyed as (
    select
    ruled.*,
    CASE WHEN place_county.county_fips IS NOT NULL THEN place_county.county_name || ', ' || place_state.state_name WHEN (ruled."county_fips" IS NULL OR ruled."county_fips" = '000') THEN place_state.state_name ELSE 'FIPS ' || ruled."state_fips" || coalesce(ruled."county_fips", '') END AS "_p_label",
    CASE WHEN place_county.county_fips IS NOT NULL THEN 'US-' || place_county.state_fips || place_county.county_fips WHEN (ruled."county_fips" IS NULL OR ruled."county_fips" = '000') AND place_state.state_fips IS NOT NULL THEN 'US-' || place_state.state_fips ELSE NULL END AS "_p_whole",
    NULL AS "_p_decl_key",
    NULL AS "_p_decl_parent",
    NULL AS "_p_decl_note",
    NULL AS "_p_note",
    try_cast(ruled."year" AS BIGINT) AS "_t_year",
    NULL AS "_t_week"
  from ruled
  left join {{ ref('stg_census_fips_state') }} as place_state
  on place_state.state_fips = ruled."state_fips"
  left join {{ ref('stg_census_fips_county') }} as place_county
  on place_county.state_fips = ruled."state_fips" and place_county.county_fips = ruled."county_fips"
)

select
  keyed.* exclude ("_p_label", "_p_whole", "_p_decl_key", "_p_decl_parent", "_p_decl_note", "_p_note", "_t_year", "_t_week"),
  CAST(CASE WHEN NULL IS NULL THEN NULL ELSE 'census_county_pop:' || NULL END AS VARCHAR) AS "condition_key",
  CAST(NULL AS VARCHAR) AS "condition_label",
  CAST(NULL AS VARCHAR) AS "condition_case_status",
  CAST(NULL AS VARCHAR) AS "condition_case_subtype",
  CAST(CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/census_county_pop:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END AS VARCHAR) AS "place_key",
  CAST(keyed._p_label AS VARCHAR) AS "place_label",
  CAST(CASE WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN coalesce(keyed._p_decl_parent, keyed._p_whole) ELSE NULL END AS VARCHAR) AS "place_parent_key",
  CAST(coalesce((keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)), false) AS BOOLEAN) AS "place_is_partial",
  CAST(CASE WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) AND coalesce(keyed._p_decl_parent, keyed._p_whole) IS NOT NULL THEN coalesce(keyed._p_decl_note, keyed._p_note) WHEN (CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/census_county_pop:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END) IS NULL THEN 'unresolved: the contract does not declare this place label and it is not a name or code in the Census code files' ELSE NULL END AS VARCHAR) AS "place_note",
  CAST(CASE WHEN (CASE WHEN keyed._p_label IS NULL THEN NULL WHEN keyed._p_decl_key IS NOT NULL THEN keyed._p_decl_key WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN CASE WHEN coalesce(keyed._p_decl_parent, keyed._p_whole) IS NULL THEN NULL ELSE coalesce(keyed._p_decl_parent, keyed._p_whole) || '/census_county_pop:' || trim(regexp_replace(lower(trim(keyed._p_label)), '[^a-z0-9]+', '-', 'g'), '-') END ELSE keyed._p_whole END) IS NULL THEN 'unresolved' WHEN (keyed._p_decl_key IS NULL AND (keyed._p_decl_parent IS NOT NULL OR keyed._p_note IS NOT NULL)) THEN 'partial_area' ELSE 'resolved' END AS VARCHAR) AS "place_status",
  CAST(CAST(NULL AS BIGINT) AS BIGINT) AS "mmwr_year",
  CAST(CAST(NULL AS BIGINT) AS BIGINT) AS "mmwr_week",
  CAST(CASE WHEN keyed._t_year IS NULL THEN NULL ELSE 'Y' || CAST(keyed._t_year AS VARCHAR) END AS VARCHAR) AS "time_key",
  CAST('year' AS VARCHAR) AS "time_grain",
  CAST('July 1 of the year (the estimate''s reference date)' AS VARCHAR) AS "date_basis"
from keyed
